"""Runs the five example questions of the case study PDF (verbatim wording) through the PRODUCT configuration (vgpt.product.make_brain, no model) on two vehicle histories and writes the answers verbatim to results/five_questions.md.
When the assistant asks a clarification, the scripted user reply "1" (accept the first offered reading) is sent and its answer is shown as well; that second answer is conditional on the reply and is labelled so. Nothing is edited by hand."""
import os, sys, time
HERE = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); sys.path.insert(0, HERE)
from vgpt.product import make_legacy_brain as make_brain
from bench.route_audit import PDF as QS
VEH = [("gen_courier_ext", 1790406000), ("gen_demo", None)]
out = ["# The case study's five example questions, answered by the assistant (verbatim)\n", "Product configuration (`vgpt.product.make_brain`: rules + clarification-first policy, no language model); time of each answer in ms. Generated by `bench/five_questions.py`.\n"]
for name, now in VEH:
    b = make_brain(os.path.join(HERE, "data", name + ".db"), now=now); out.append(f"\n## Vehicle history `{name}`\n")
    for q in QS:
        b.qcs = type(b.qcs)(); b.trace.__init__()
        t = time.perf_counter(); r = b.ask(q, use_slm=False); ms = (time.perf_counter() - t) * 1000
        out.append(f"**{q}**  ({ms:.0f} ms, route `{r.get('path')}`)\n\n```\n{(r.get('answer') or '').strip()}\n```\n")
        if r.get("intent") == "CLARIFY":
            t = time.perf_counter(); r2 = b.ask("1", use_slm=False); ms = (time.perf_counter() - t) * 1000
            out.append(f"*Scripted reply \"1\" (the first reading offered)*  ({ms:.0f} ms, route `{r2.get('path')}`)\n\n```\n{(r2.get('answer') or '').strip()}\n```\n")
open(os.path.join(HERE, "results", "five_questions.md"), "w", encoding="utf-8").write("\n".join(out)); print("written", len(QS) * len(VEH), "questions")
